import{_ as n,c as t,o as s,j as a,a as l}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"南轩易说","description":"南轩易说 - 南轩易说","frontmatter":{"title":"南轩易说","description":"南轩易说 - 南轩易说"},"headers":[],"relativePath":"zh/classics/nanxuan/001.md","filePath":"zh/classics/nanxuan/001.md"}'),r={name:"zh/classics/nanxuan/001.md"};function c(o,e,i,p,d,u){return s(),t("div",null,[...e[0]||(e[0]=[a("h1",{id:"南轩易说",tabindex:"-1"},[l("南轩易说 "),a("a",{class:"header-anchor",href:"#南轩易说","aria-label":"Permalink to “南轩易说”"},"​")],-1),a("p",null,"钦定四库全书经部一",-1),a("p",null,"易类提要",-1),a("p",null,"臣 等谨案：南轩易说，宋张栻撰。案曹学佺蜀中广记载是书十一卷，以为张浚所作。考浚紫岩易传，其本犹存，与此别为一书，学佺殊误。朱彝尊经义考亦作十一卷，注云「未见」，又引董真卿说已阙乾、坤二卦。此本乃嘉兴曹溶从至元壬辰赣州路儒学学正胡顺父刊本传写，并六十四卦皆佚之，仅始于系辞「天一地二」一章，较真卿所见弥为残缺。然卷端题曰「系辞上卷下」，而顺父序称「鲁人东泉王公分司廉访章贡等路，公余讲论，尝诵伊川易传，特阙系辞，留心访求，因得南轩解说易系，缮写家藏，傥合以并传，斯为完书。乃出示知事吴将仕，刊之学宫，以补遗缺，使与周易程氏传大字旧本同传于世」云云。是初刊此书，亦仅托始于系辞，溶所传写，仅佚其上卷之上耳。序末有钩摹旧本三小印：一作「谦卦」；一曰「赣州胡氏」，知顺父即赣人；一曰和卿，盖其字也。乾隆四十六年二月恭校上。",-1),a("p",null,"总纂官 臣 纪昀、 臣 陆锡熊、 臣 孙士毅，总校官 臣 陆费墀。南轩易说序",-1),a("p",null,"昔尹和靖语学者祁宽曰：「与其读他书，不若专读易；与其看伊川杂说，不若专看伊川易传。」又曰：「一日只念一卦，闲时看系辞。」周易程氏传止于卦而不及系，非不及也，以系辞为易大传，不暇及也。然易系曰：",-1),a("p",null,"「易有圣人之道四焉：以言者尚其辞，以动者尚其变，以制器者尚其象，以卜筮者尚其占。」其通论一经之大体如此，不传奚可？伊川议论，虽间见于遗书，而终未完，学者惜之。至元壬辰，鲁人东泉王公分司廉访章贡等路，公余讲论，因言辞谢衰病，家食数年，从事于易，尝诵伊川易传，特阙系辞，留心访求，遂得南轩解说易系，缮写家藏，好玩如宝。圣人之言：「无有师保，如临父母。」钦哉钦哉！傥合以并传，斯为完书。乃出示知事吴将仕及路学宿儒，议若命工刊之学宫，以补遗阙，使与周易程氏传大字旧本并行于世，可乎？将仕洎诸儒复命曰：「斯文也，盖有待于今日也，后之学者幸莫大焉。」顺父承命校正，敬录以付匠氏，并序其槩于后。是岁季冬既望，赣州路儒学学正权管学事胡顺父序。",-1)])])}const f=n(r,[["render",c]]);export{_ as __pageData,f as default};
